const tasks = [
  { title: "Matematik ödevi", done: false },
  { title: "Fizik tekrarı", done: false },
  { title: "Kitap okuma", done: false },
];
let selected = 0;
const list = document.querySelector("#tasks");

function render() {
  list.innerHTML = "";
  tasks.forEach((task, i) => {
    const li = document.createElement("li");
    li.textContent = task.title;
    li.classList.toggle("done", task.done);
    li.classList.toggle("selected", i === selected);
    list.append(li);
  });
}

function select(delta) {
  selected = Math.min(tasks.length - 1, Math.max(0, selected + delta));
  render();
}

function toggleSelected() {
  tasks[selected].done = !tasks[selected].done;
  render();
}

// aria-label'lar; düğmeler ve tuşlar (ArrowUp, ArrowDown, x)
const upBtn = document.querySelector("#up");
const downBtn = document.querySelector("#down");
upBtn.setAttribute("aria-label", "Yukarı");
downBtn.setAttribute("aria-label", "Aşağı");
upBtn.addEventListener("click", () => select(-1));
downBtn.addEventListener("click", () => select(1));
document.querySelector("#toggle").addEventListener("click", toggleSelected);
document.addEventListener("keydown", (e) => {
  if (e.key === "ArrowUp") select(-1);
  if (e.key === "ArrowDown") select(1);
  if (e.key === "x") toggleSelected();
});

render();

check.js:
assert($("#up").getAttribute("aria-label") === "Yukarı" && $("#down").getAttribute("aria-label") === "Aşağı", "▲ ve ▼ düğmelerinin aria-label'ları 'Yukarı' ve 'Aşağı' olmalı.");
const li = (i) => $$("#tasks li")[i];
click("#down");
assert(selected === 1 && li(1).classList.contains("selected"), "▼ düğmesi seçimi bir aşağı taşımalı.");
key("ArrowDown");
key("ArrowDown");
assert(selected === 2, "Seçim son görevin ötesine geçmemeli.");
key("x");
assert(tasks[2].done === true && li(2).classList.contains("done"), "x tuşu seçili görevi tamamlamalı.");
click("#toggle");
assert(tasks[2].done === false && !li(2).classList.contains("done"), "Tamamla düğmesi aynı işi yapmalı (yeniden açmalı).");
key("ArrowUp");
click("#up");
click("#up");
assert(selected === 0 && li(0).classList.contains("selected"), "Seçim ilk görevin önüne geçmemeli.");

