project_task.solution:
const questions = [
  { soru: "Ay, hangi gezegenin uydusudur?", secenekler: ["Mars", "Dünya", "Jüpiter"], dogru: 1 },
  { soru: "Güneş sistemindeki en büyük gezegen hangisidir?", secenekler: ["Satürn", "Jüpiter", "Neptün"], dogru: 1 },
];
let current = 0;
let score = 0;
let answered = false;
const optionButtons = document.querySelectorAll("#options button");
const feedback = document.querySelector("#feedback");

function showQuestion() {
  const q = questions[current];
  document.querySelector("#question").textContent = q.soru;
  optionButtons.forEach((btn, i) => {
    btn.textContent = `${i + 1}) ${q.secenekler[i]}`;
  });
  feedback.textContent = "";
  answered = false;
}

function choose(i) {
  if (answered) return;
  answered = true;
  const q = questions[current];
  if (i === q.dogru) {
    score += 10;
    feedback.textContent = "Doğru!";
  } else {
    feedback.textContent = `Yanlış! Doğru cevap: ${q.secenekler[q.dogru]}`;
  }
  document.querySelector("#score").textContent = `Puan: ${score}`;
}

document.querySelector("#next").addEventListener("click", () => {
  current = (current + 1) % questions.length;
  showQuestion();
});

// aria-live; seçenek tıklamaları; 1, 2, 3 tuşları
feedback.setAttribute("aria-live", "polite");
optionButtons.forEach((btn) => {
  btn.addEventListener("click", () => choose(Number(btn.dataset.i)));
});
document.addEventListener("keydown", (e) => {
  if (["1", "2", "3"].includes(e.key)) choose(Number(e.key) - 1);
});

showQuestion();

check.js:
assert($("#feedback").getAttribute("aria-live") === "polite", "#feedback'in aria-live değeri 'polite' olmalı.");
key("2");
assert($("#feedback").textContent.trim() === "Doğru!" && score === 10, "2 tuşu ikinci şıkkı (Dünya) seçmeli: 'Doğru!' ve puan 10.");
assert($("#score").textContent.trim() === "Puan: 10", "#score 'Puan: 10' olmalı.");
key("1");
assert($("#feedback").textContent.trim() === "Doğru!" && score === 10, "Cevaplanmış soruya ikinci cevap sayılmamalı.");
click("#next");
click('#options button[data-i="0"]');
assert($("#feedback").textContent.trim() === "Yanlış! Doğru cevap: Jüpiter" && score === 10, "Yanlış şıkta 'Yanlış! Doğru cevap: Jüpiter' yazmalı, puan değişmemeli.");
click("#next");
click('#options button[data-i="1"]');
assert(score === 20 && $("#score").textContent.trim() === "Puan: 20", "Düğmeyle verilen doğru cevap da puanı artırmalı.");
